import os,sys
os.chdir('/app')
R=int(sys.argv[1]); svc=sys.argv[2]; env='prod-b'; host='app-07'
revs=sorted(int(d[1:]) for d in os.listdir('config-history') if d.startswith('r'))
def real(rel):
    for r in revs:
        if r>R:
            p=f'config-history/r{r:04d}/prev/{rel}'
            if os.path.exists(p): return p
    return 'config/'+rel
def run(rel,vals):
    sec=None
    for l in open(real(rel)):
        l=l.strip()
        if not l or l.startswith('#'): continue
        if l.startswith('[') and l.endswith(']'): sec=l[1:-1]; continue
        k,_,v=[x.strip() for x in l.partition('=')]
        if k=='include':
            if sec is None:
                t=v.replace('${env}',env).replace('${host}',host)
                run(os.path.normpath(os.path.join(os.path.dirname(rel),t)),vals)
            continue
        if sec is None or sec==svc: vals[k]=v
def service(s):
    global svc
    svc=s
    vals={}
    for l in open(f'services/{s}/service.conf'):
        l=l.strip()
        if not l or l.startswith('#'): continue
        k,_,v=[x.strip() for x in l.partition('=')]
        if k=='include':
            t=os.path.normpath(os.path.join(f'services/{s}',v.replace('${env}',env).replace('${host}',host)))
            run(os.path.relpath(t,'config'),vals)
        else: vals[k]=v
    return vals
for s in sorted(os.listdir('services')) if svc=='all' else [svc]:
    v=service(s)
    try: m=int(v['port_base'])+int(v['port_offset'])
    except Exception: m=None
    print(s,v.get('enabled'),m,v.get('admin_port'))

